import fs from 'node:fs'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const ERRS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (e) => ({ t: 'err', v: e })
const num = (v) => ({ t: 'num', v })

function parseAddr(w) {
  const m = /^([A-Z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const c = m[1]
  const col = c.length === 1 ? c.charCodeAt(0) - 64 : (c.charCodeAt(0) - 64) * 26 + (c.charCodeAt(1) - 64)
  return { col, row }
}
const key = (col, row) => col * 1000 + row
function name(col, row) {
  const l = col <= 26 ? String.fromCharCode(64 + col) : String.fromCharCode(64 + Math.floor((col - 1) / 26)) + String.fromCharCode(65 + ((col - 1) % 26))
  return l + row
}

// ---- parse sheet
const input = fs.readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  let s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const raw = m[0]
  const content = s.slice(raw.length).replace(/^[ \t]+/, '')
  const up = raw.toUpperCase()
  const a = parseAddr(up)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${up}\n`)
    process.exit(2)
  }
  const k = key(a.col, a.row)
  if (cells.has(k)) {
    process.stderr.write(`error: line ${i + 1}: cell ${up} is declared twice\n`)
    process.exit(2)
  }
  cells.set(k, { col: a.col, row: a.row, content })
}

// ---- formula parser
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'n', v: m[0] }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'w', v: m[0].toUpperCase() }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(src.slice(i)))) {
      toks.push({ k: 'o', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new Error('parse') }
  const isOp = (v) => p < toks.length && toks[p].k === 'o' && toks[p].v === v
  function expr() {
    let l = add()
    while (p < toks.length && toks[p].k === 'o' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { type: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p++]
    if (t.k === 'n') return { type: 'num', v: Number(t.v) }
    if (t.k === 'o') {
      if (t.v === '(') {
        const e = expr()
        if (!isOp(')')) fail()
        p++
        return e
      }
      fail()
    }
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++ } else {
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { type: 'call', name: t.v, args }
    }
    if (t.v === 'TRUE') return { type: 'bool', v: true }
    if (t.v === 'FALSE') return { type: 'bool', v: false }
    return { type: 'ref', w: t.v }
  }
  function arg() {
    if (p + 3 < toks.length + 0 && toks[p].k === 'w' && toks[p + 1].k === 'o' && toks[p + 1].v === ':' && toks[p + 2].k === 'w' &&
      toks[p + 3].k === 'o' && (toks[p + 3].v === ',' || toks[p + 3].v === ')')) {
      const r = { type: 'range', a: toks[p].v, b: toks[p + 2].v }
      p += 3
      return r
    }
    return expr()
  }
  try {
    const e = expr()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e.message === 'parse') return null
    throw e
  }
}

// ---- evaluation
const memo = new Map()
const busy = new Set()

function cellValue(col, row) {
  const k = key(col, row)
  if (memo.has(k)) return memo.get(k)
  const c = cells.get(k)
  if (!c) return num(0)
  if (busy.has(k)) return err('#CYCLE!')
  busy.add(k)
  const v = evalContent(c)
  busy.delete(k)
  memo.set(k, v)
  return v
}

function evalContent(c) {
  const s = c.content
  if (s[0] === '=') {
    if (!c.ast) c.ast = parseFormula(s.slice(1)) || 'bad'
    if (c.ast === 'bad') return err('#ERR!')
    return ev(c.ast)
  }
  if (s === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRS.has(s)) return err(s)
  return { t: 'text', v: s }
}

function toNum(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  if (v.t === 'text') return err('#VALUE!')
  return v
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

function rank(v) { return v.t === 'num' ? 0 : v.t === 'text' ? 1 : 2 }
function cmpCP(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}
function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.t === 'text') return cmpCP(a.v, b.v)
  const x = a.t === 'bool' ? +a.v : a.v, y = b.t === 'bool' ? +b.v : b.v
  return x < y ? -1 : x > y ? 1 : 0
}

function refValue(w) {
  const a = parseAddr(w)
  if (!a) return err('#REF!')
  return cellValue(a.col, a.row)
}

// returns list of values (an error value for bad range)
function expand(arg) {
  if (arg.type !== 'range') return [ev(arg)]
  const a = parseAddr(arg.a), b = parseAddr(arg.b)
  if (!a || !b) return [err('#REF!')]
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(cellValue(c, r))
  return out
}

function ev(n) {
  switch (n.type) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'bool', v: n.v }
    case 'ref': return refValue(n.w)
    case 'un': {
      const v = toNum(ev(n.e))
      if (v.t === 'err') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'bin': {
      const l = ev(n.l)
      if (l.t === 'err') return l
      const r = ev(n.r)
      if (r.t === 'err') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        const res = n.op === '=' ? d === 0 : n.op === '<>' ? d !== 0 : n.op === '<' ? d < 0 : n.op === '<=' ? d <= 0 : n.op === '>' ? d > 0 : d >= 0
        return { t: 'bool', v: res }
      }
      const x = toNum(l)
      if (x.t === 'err') return x
      const y = toNum(r)
      if (y.t === 'err') return y
      switch (n.op) {
        case '+': return fin(x.v + y.v)
        case '-': return fin(x.v - y.v)
        case '*': return fin(x.v * y.v)
        case '/': return y.v === 0 ? err('#DIV/0!') : fin(x.v / y.v)
        case '^': return fin(Math.pow(x.v, y.v))
      }
      return err('#ERR!')
    }
    case 'call': return call(n)
    case 'range': return err('#ERR!')
  }
  return err('#ERR!')
}

function scalar(arg) {
  const vs = expand(arg)
  if (vs.length === 1) return vs[0]
  return err('#ERR!')
}

function call(n) {
  const f = n.name, args = n.args
  const multi = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
  if (multi.includes(f)) {
    if (args.length < 1) return err('#ERR!')
    const vals = []
    for (const a of args) {
      for (const v of expand(a)) {
        if (v.t === 'err') return v
        vals.push(v)
      }
    }
    if (f === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'err') return x
      nums.push(x.v)
    }
    if (f === 'SUM') return fin(nums.reduce((a, b) => a + b, 0))
    if (f === 'AVG') return nums.length ? (nums.length === 0 ? err('#DIV/0!') : fin(nums.reduce((a, b) => a + b, 0) / nums.length)) : err('#DIV/0!')
    if (f === 'MIN') return num(nums.reduce((a, b) => (b < a ? b : a)))
    return num(nums.reduce((a, b) => (b > a ? b : a)))
  }
  if (f === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const v = scalar(args[0])
    if (v.t === 'err') return v
    const x = toNum(v)
    if (x.t === 'err') return x
    return num(Math.abs(x.v))
  }
  if (f === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const c = scalar(args[0])
    if (c.t === 'err') return c
    let truth
    if (c.t === 'bool') truth = c.v
    else if (c.t === 'num') truth = c.v !== 0
    else return err('#VALUE!')
    return scalar(truth ? args[1] : args[2])
  }
  return err('#NAME?')
}

// ---- output
function fmt(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function collect(n, set) {
  if (!n || typeof n !== 'object') return
  if (n.type === 'ref') {
    const a = parseAddr(n.w)
    if (a) set.set(key(a.col, a.row), a)
  } else if (n.type === 'range') {
    const a = parseAddr(n.a), b = parseAddr(n.b)
    if (a && b) {
      for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
        for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) set.set(key(c, r), { col: c, row: r })
    }
  } else if (n.type === 'bin') { collect(n.l, set); collect(n.r, set) }
  else if (n.type === 'un') collect(n.e, set)
  else if (n.type === 'call') n.args.forEach((a) => collect(a, set))
}

const order = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
const out = []
for (const c of order) {
  const addr = name(c.col, c.row)
  if (mode === 'values') out.push(`${addr}=${fmt(cellValue(c.col, c.row))}`)
  else {
    const set = new Map()
    if (c.content[0] === '=') collect(parseFormula(c.content.slice(1)), set)
    const l = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out.push(`${addr}:` + l.map((x) => ' ' + name(x.col, x.row)).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
